<?php
declare(strict_types=1);

function h(mixed $v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function j(mixed $v): string { return json_encode($v,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR); }
function page(string $title,string $content,string $scripts='',string $endpoint=''): never {
    $s=settings();$base=h(base_path());$csrf=h($_SESSION['csrf']??'');$site=h($s['title']);$chat=$endpoint==='chat_page'?'chat-page':'';
    $bankOptions='';foreach(banks()as$b)$bankOptions.='<option value="'.h($b['id']).'" '.($b['id']===bank_id()?'selected':'').'>'.h($b['name']).'</option>';
    $bankUi='<div class="bank-switcher"><form class="bank-select-form" method="post" action="'.h(app_url('/banks/select')).'"><input type="hidden" name="_csrf" value="'.$csrf.'"><label><span class="sr-only">Kunskapsbank</span><select name="bank" aria-label="Välj kunskapsbank" onchange="this.form.submit()">'.$bankOptions.'</select></label></form><details><summary title="Skapa kunskapsbank"><span aria-hidden="true">＋</span><span>Ny bank</span></summary><form class="bank-create-form" method="post" action="'.h(app_url('/banks/create')).'"><input type="hidden" name="_csrf" value="'.$csrf.'"><label><span>Ny kunskapsbank</span><input name="name" maxlength="80" placeholder="Exempel: Projekt Atlas" required></label><button class="btn-primary">Skapa</button></form></details></div>';
    echo '<!doctype html><html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="app-base" content="'.$base.'"><meta name="csrf-token" content="'.$csrf.'"><title>'.h($title).' – '.$site.'</title><link rel="icon" href="'.h(url_for('static',filename:'favicon.svg')).'" type="image/svg+xml"><link rel="stylesheet" href="'.h(url_for('static',filename:'style.css')).'"><link rel="stylesheet" href="'.h(url_for('static',filename:'workspace.css')).'"><link rel="stylesheet" href="'.h(url_for('static',filename:'navigation.css')).'"><script>document.documentElement.setAttribute("data-theme",localStorage.getItem("theme")||"light")</script><script src="'.h(url_for('static',filename:'php-bridge.js')).'"></script></head><body class="'.$chat.'"><header class="site-header"><a class="brand" href="'.h(url_for('browse')).'">'.$site.'</a>'.$bankUi.'<button id="nav-toggle" type="button" class="nav-toggle" aria-expanded="false" aria-controls="main-nav"><span aria-hidden="true">☰</span><span class="sr-only">Öppna meny</span></button><nav id="main-nav">'.nav('browse','Bläddra',$endpoint).nav('skills_page','Skills',$endpoint).nav('chat_page','Chatta',$endpoint).nav('new_doc','＋ Nytt',$endpoint).nav('upload_documents','Ladda upp',$endpoint).'<button id="reindex-btn" type="button" class="btn-secondary">↻ Uppdatera</button></nav><div class="header-actions"><button id="theme-toggle" class="header-icon" type="button">◐</button><button id="settingsBtn" class="header-icon" type="button">⚙</button><button id="helpBtn" class="header-help" type="button"><span>?</span><span class="help-label">Hjälp</span></button></div></header><main>'.$content.'</main><footer class="site-footer"><span>'.$site.' · PHP · '.h($_SERVER['HTTP_HOST']??'localhost').'</span>'.(!empty($_SESSION['authenticated'])?'<form method="post" action="'.h(app_url('/logout')).'"><button class="btn-secondary">Logga ut</button></form>':'').'</footer><div id="toast" class="toast" role="status" hidden></div><dialog id="helpDialog" class="help-dialog"><div class="help-dialog-head"><h2>Hjälp · Kunskapstratten</h2><button id="helpClose" type="button" class="header-icon">✕</button></div><iframe id="helpFrame" data-src="'.h(url_for('help_guide')).'" title="Guide"></iframe></dialog><script src="'.h(url_for('static',filename:'app.js')).'"></script><script src="'.h(url_for('static',filename:'llm-client.js')).'"></script><script src="'.h(url_for('static',filename:'import-ai.js')).'"></script>'.file_get_contents(dirname(__DIR__).'/templates/settings.html').'<script src="'.h(url_for('static',filename:'settings.js')).'"></script>'.$scripts.'</body></html>';exit;
}
function nav(string $route,string $label,string $active): string{return '<a href="'.h(url_for($route)).'" class="'.($active===$route?'is-active':'').'">'.h($label).'</a>';}
function doc_picker(array $docs,array $selected=[]): string {$x='<fieldset class="skill-document-picker"><legend>Förvalda KB-dokument</legend><input type="search" id="skillDocumentFilter" placeholder="Sök titel, tagg eller sökväg…"><p id="skillDocumentCount"></p><div class="document-picker-list" id="skillDocumentList">';foreach($docs as$d){$search=mb_strtolower($d['title'].' '.$d['rel_path'].' '.implode(' ',$d['tags']));$x.='<label data-search="'.h($search).'"><input type="checkbox" name="documents[]" value="'.h($d['rel_path']).'" '.(in_array($d['rel_path'],$selected,true)?'checked':'').'><span><strong>'.h($d['title']).'</strong><small>'.h($d['rel_path']).'</small></span></label>';}$x.='</div></fieldset><script>(()=>{const r=[...document.querySelectorAll("#skillDocumentList label")],c=document.getElementById("skillDocumentCount"),u=()=>c.textContent=r.filter(x=>x.querySelector("input").checked).length+" dokument valda";r.forEach(x=>x.querySelector("input").onchange=u);document.getElementById("skillDocumentFilter").oninput=e=>r.forEach(x=>x.hidden=!x.dataset.search.includes(e.target.value.toLowerCase().trim()));u()})()</script>';return$x;}
function editor_page(string $rel,string $raw,bool $skill): never {
    $id=$skill?'saveSkillBtn':'saveDocBtn';$api=url_for($skill?'save_skill':'save_doc',relpath:$rel);
    $back=url_for($skill?'skills_page':'view_doc',...($skill?[]:['relpath'=>$rel]));$kind=$skill?'skill':'doc';
    $content='<section class="edit-view"><a class="back-link" href="'.h($back).'">← Tillbaka</a><h1 class="edit-title">Redigerar <code>'.h($rel).'</code></h1><div id="monacoEditor" class="monaco-host"></div><textarea id="editArea" class="edit-textarea editor-fallback" spellcheck="false">'.h($raw).'</textarea><div class="edit-actions"><button class="btn-primary" id="'.$id.'">Spara</button><button class="btn-secondary" id="formatMarkdownBtn" type="button">Snygga till</button><button class="btn-secondary" id="undoFormatBtn" type="button" hidden>Ångra uppsnyggning</button><button class="btn-danger" id="deleteItemBtn" data-url="'.h(url_for('delete_item',kind:$kind,relpath:$rel)).'" data-back="'.h($skill?url_for('skills_page'):url_for('browse')).'">Radera</button><a class="btn-secondary" href="'.h($back).'">Avbryt</a><span id="saveStatus" role="status"></span></div><script id="editor-data" type="application/json">'.j(['saveId'=>$id,'saveUrl'=>$api,'backUrl'=>$back,'kind'=>$kind,'relpath'=>$rel]).'</script></section>';
    $scripts='<script src="'.h(url_for('static',filename:'delete-editor.js')).'"></script><script src="https://cdn.jsdelivr.net/npm/monaco-editor@latest/min/vs/loader.js"></script><script src="'.h(url_for('static',filename:'markdown-editor.js')).'"></script>';
    page('Redigera',$content,$scripts);
}

function render(string $template,array $d=[],string $endpoint=''): never {
    ob_start();
    if($template==='login.html'){echo '<section class="form-page"><h1>'.h(settings()['title']).'</h1><p>Logga in för att öppna kunskapsbanken.</p>'.(!empty($d['error'])?'<p class="form-error">'.h($d['error']).'</p>':'').'<form method="post" action="'.h(app_url('/login')).'"><input type="hidden" name="_csrf" value="'.h($_SESSION['csrf']).'"><label>Lösenord <input type="password" name="password" required autofocus></label><p><button class="btn-primary">Logga in</button></p></form></section>';page('Logga in',ob_get_clean());}
    if($template==='new.html'){echo '<section class="edit-view"><a class="back-link" href="'.h(url_for('browse')).'">← Bläddra</a><h1>Skapa nytt dokument</h1><form method="post" class="new-doc-form"><label>Titel <input name="title" required></label><label>Mapp <input name="folder" placeholder="exempel/projekt"></label><label>Taggar <input name="tags" placeholder="planering, möte"></label><label>Innehåll <textarea name="body" placeholder="# Rubrik"></textarea></label><div class="edit-actions"><button class="btn-primary">Skapa dokument</button></div></form></section>';page('Nytt dokument',ob_get_clean(),'',$endpoint);}
    if($template==='upload.html'){echo '<section class="form-page"><h1>Ladda upp till inbox</h1>';if(!empty($d['saved']))echo '<div class="result-panel success"><strong>'.count($d['saved']).' filer uppladdade</strong><button id="processUploaded" class="btn-primary">Bearbeta nu</button></div>';foreach($d['rejected']??[]as$x)echo'<p class="form-error">'.h($x).'</p>';echo'<form method="post" enctype="multipart/form-data" class="upload-form"><label id="dropZone" class="drop-zone"><input id="fileInput" type="file" name="files[]" multiple required><strong>Dra filer hit eller välj från datorn</strong><span id="fileSummary">Flera filer kan väljas</span></label><label class="field-label">Undermapp <input name="folder"></label><button class="btn-primary">Ladda upp filer</button></form></section>';$sc='<script>(()=>{const i=document.getElementById("fileInput"),s=document.getElementById("fileSummary");i.onchange=()=>s.textContent=i.files.length+" filer valda";const b=document.getElementById("processUploaded");if(b)b.onclick=async()=>{const x=await postJSON("/api/reindex",{});if(x.ingest.failed||x.ingest.warnings.length)showToast([...x.ingest.errors,...x.ingest.warnings].join("; "));else location.href='.j(url_for('browse')).'}})()</script>';page('Ladda upp',ob_get_clean(),$sc,$endpoint);}
    if($template==='edit.html')editor_page($d['relpath'],$d['raw'],false);if($template==='edit_skill.html')editor_page($d['relpath'],$d['raw'],true);
    if($template==='doc.html'){echo'<article class="doc-view"><div class="doc-toolbar"><a href="'.h(url_for('browse')).'">← Bläddra</a><div class="doc-toolbar-actions"><a class="btn-primary" href="'.h(url_for('chat_page',doc:$d['relpath'])).'">Chatta om detta</a><a class="btn-secondary" href="'.h(url_for('edit_doc',relpath:$d['relpath'])).'">Redigera</a><a class="btn-secondary" href="'.h(url_for('download_doc',relpath:$d['relpath'])).'">Ladda ned .md</a></div></div><header class="doc-header"><h1>'.h($d['doc']['title']).'</h1><div class="card-tags">';foreach($d['doc']['tags']as$t)echo'<a class="tag-chip small" href="'.h(url_for('browse',tag:$t)).'">#'.h($t).'</a>';echo'</div></header><details class="frontmatter-panel"><summary>YAML-frontmatter</summary><pre>'.h(Store::yamlDump($d['frontmatter'])).'</pre></details><div class="doc-body">'.$d['html_body'].'</div></article>';page($d['doc']['title'],ob_get_clean(),'',$endpoint);}
    if($template==='skills.html'){echo'<section class="skills-view"><div class="page-heading"><div><h1>Bearbetningsskills</h1><p>Skills bearbetar valda dokument.</p></div><a class="btn-primary" href="'.h(url_for('new_skill')).'">Skapa skill</a></div><div class="card-grid skill-card-grid">';foreach($d['custom_skills']as$s)echo'<article class="skill-card"><span class="stamp">funktion</span><h3>'.h($s['name']).'</h3><p>'.h($s['description']).'</p><div class="skill-actions"><a class="btn-primary" href="'.h(url_for('run_skill_page',slug:$s['slug'])).'">Kör skill</a><a class="btn-secondary" href="'.h(url_for('skill_documents',slug:$s['slug'])).'">Välj dokument</a><a class="btn-secondary" href="'.h(url_for('edit_skill',relpath:$s['rel_path'])).'">Redigera kod</a></div></article>';echo'</div></section>';page('Skills',ob_get_clean(),'',$endpoint);}
    if($template==='new_skill.html'){echo'<section class="form-page"><h1>Skapa egen skill</h1><form method="post" class="skill-form"><label>Namn<input name="name" required></label><label>Beskrivning<textarea name="description" required></textarea></label><label>Instruktioner<textarea name="instructions" rows="8"></textarea></label>'.doc_picker($d['docs']).'<button class="btn-primary">Skapa skill</button></form></section>';page('Skapa skill',ob_get_clean());}
    if($template==='skill_documents.html'){echo'<section class="form-page"><h1>Dokument för '.h($d['skill']['name']).'</h1><form method="post"><input type="hidden" name="version" value="'.h($d['version']).'">'.doc_picker($d['docs'],$d['selected_documents']).'<button class="btn-primary">Spara dokumentval</button></form></section>';page('Dokument för '.$d['skill']['name'],ob_get_clean());}
    if($template==='browse.html')browse_view($d,$endpoint);
    if($template==='chat.html')chat_view($d,$endpoint);
    if($template==='run_skill.html')run_view($d,$endpoint);
    throw new RuntimeException('Okänd vy: '.$template,500);
}
function browse_view(array$d,string$endpoint):never{$url=fn(array$x=[])=>url_for('browse',...array_replace(array_diff_key($_GET,['r'=>1]),$x));echo'<header class="browse-page-head"><div><h1>Kunskapsbanken</h1><p>'.$d['total_docs'].' dokument</p></div><div class="page-actions"><a class="btn-secondary" href="'.h(url_for('upload_documents')).'">⇧ Ladda upp</a><a class="btn-primary" href="'.h(url_for('new_doc')).'">＋ Nytt dokument</a></div></header><section class="index-toolbar"><form method="get" class="search-form"><input type="hidden" name="r" value="/browse"><div class="search-primary"><input type="search" name="q" value="'.h($d['q']).'" placeholder="Sök i titel, metadata och hela dokumentet…"><button class="btn-primary">⌕ Sök</button></div><div class="browse-quickbar"><p>Visar '.$d['first_result'].'–'.$d['last_result'].' av '.$d['result_count'].' träffar</p><nav class="view-switch">';foreach(['cards'=>'▦ Kort','list'=>'☷ Lista','table'=>'▤ Tabell']as$v=>$l)echo'<a class="'.($d['view']===$v?'is-active':'').'" href="'.h($url(['view'=>$v])).'">'.$l.'</a>';echo'</nav></div></form><details class="browse-tags"><summary>Taggar <span class="count-badge">'.$d['tag_count'].'</span></summary><div class="tag-row">';foreach($d['tags']as$t)echo'<a class="tag-chip" href="'.h($url(['tag'=>$t,'page'=>1])).'">#'.h($t).' <span>'.$d['tag_counts'][$t].'</span></a>';echo'</div></details></section>';
if($d['view']==='table')echo'<div class="browse-table-wrap"><table class="browse-table"><thead><tr><th>Artikel</th><th>Taggar</th><th>Typ</th></tr></thead><tbody>';else echo'<div class="'.($d['view']==='cards'?'card-grid browse-cards':'browse-list').'">';foreach($d['docs']as$x){$tags='';foreach(array_slice($x['tags'],0,3)as$t)$tags.='<a class="tag-chip small" href="'.h($url(['tag'=>$t])).'">#'.h($t).'</a>';if($d['view']==='table')echo'<tr><td><a href="'.h(url_for('view_doc',relpath:$x['rel_path'])).'">'.h($x['title']).'</a><span class="article-path">'.h($x['rel_path']).'</span></td><td>'.$tags.'</td><td>'.h($x['source_type']).'</td></tr>';else echo'<article class="doc-card"><a class="article-content" href="'.h(url_for('view_doc',relpath:$x['rel_path'])).'"><h2>'.h($x['title']).'</h2><span class="article-path">'.h($x['rel_path']).'</span><p class="card-summary">'.h($x['search_excerpt']??$x['summary']).'</p></a><div class="card-tags">'.$tags.'</div><div class="card-footer"><span class="stamp">'.h($x['source_type']).'</span></div></article>';}echo$d['view']==='table'?'</tbody></table></div>':'</div>';echo'<nav class="browse-pagination">';foreach($d['page_numbers']as$n)echo'<a href="'.h($url(['page'=>$n])).'">'.$n.'</a>';echo'</nav>';page('Bläddra',ob_get_clean(),'',$endpoint);}
function chat_view(array$d,string$endpoint):never{echo'<div class="chat-layout"><aside class="chat-sidebar" id="chatSidebar"><div class="chat-sidebar-scroll"><div class="section-title">Aktiv skill</div><select id="chatSkillSelect"><option value="">Ingen skill – vanlig chatt</option>';foreach($d['chat_skills']as$s)echo'<option value="'.h($s['slug']).'">'.h($s['name']).'</option>';echo'</select><p id="chatSkillDescription" class="chat-sidebar-hint">Välj en skill och skicka sedan din fråga.</p><p id="chatSkillStatus"></p><div class="section-title">Lägg till dokument</div><input id="docFilter" placeholder="Filtrera dokument…"><ul class="doc-add-list" id="docAddList">';foreach($d['docs']as$x)echo'<li><label><input type="checkbox" class="doc-checkbox" value="'.h($x['rel_path']).'"><span class="dname">'.h($x['title']).'</span></label></li>';echo'</ul><div class="section-title">Tillfällig fil</div><label class="temp-file-button"><input id="tempFileInput" type="file"><span>＋ Lägg till för denna chatt</span></label><ul id="tempCtxList" class="ctx-list"></ul><p id="tempFileStatus"></p><div class="section-title">I kontext</div><ul id="ctxList" class="ctx-list"></ul><div class="ctx-bar"><span><span id="ctxCount">0</span> dokument</span><span>~<span id="ctxTokens">0</span> tokens</span></div><button id="clearCtxBtn" class="btn-secondary">Rensa</button><section class="context-meter"><h3>Kontextfönster <strong id="contextPercent">0 %</strong></h3><div id="contextProgress" class="context-meter-track"><span id="contextMeterFill"></span></div><span id="contextUsed">0</span> / <span id="contextLimit">0</span><div class="context-breakdown"><span>Underlag <strong id="contextDocs">0</strong></span><span>Konversation <strong id="contextHistory">0</strong></span><span>Skill <strong id="contextSkill">0</strong></span><span>Minne <strong id="contextMemory">0</strong></span></div></section></div></aside><div class="chat-main"><div class="chat-toolbar"><button id="toggleContext">☰ Kontext & skills</button><span class="chat-model-label">'.h($d['ai_model_label']).'</span><button id="exportChat" class="btn-secondary">Spara till KB</button></div><p id="chatExportStatus" hidden></p><div class="chat-scroll" id="chatScroll"><div class="empty-state chat-empty" id="chatEmpty"><p class="empty-title">Chatta med kunskapsbanken</p></div></div><form class="chat-composer" id="chatForm"><textarea id="chatInput" placeholder="Ställ en fråga…"></textarea><button class="btn-primary send-btn" id="chatSendBtn">➤</button></form><p class="chat-meta">'.h($d['ai_model_label']).'</p></div></div><dialog id="exportDialog" class="settings-dialog"><form id="exportForm" class="settings-body"><h2>Spara chatten</h2><label>Titel<input id="exportName" required></label><button id="exportCancel" type="button">Avbryt</button><button class="btn-primary">Spara</button><p id="exportStatus"></p></form></dialog><script id="chat-data" type="application/json">'.j($d['chat_data']).'</script><script>window.INITIAL_SELECTION='.j($d['initial_paths']).'</script>';$sc='<script src="https://cdn.jsdelivr.net/npm/marked@15/lib/marked.umd.js"></script><script src="https://cdn.jsdelivr.net/npm/dompurify@3/dist/purify.min.js"></script><script src="'.h(url_for('static',filename:'chat-renderer.js')).'"></script><script src="'.h(url_for('static',filename:'chat.js')).'"></script>';page('Chatta',ob_get_clean(),$sc,$endpoint);}
function run_view(array$d,string$endpoint):never{$s=$d['skill'];echo'<section class="skill-run-page"><h1>'.h($s['name']).'</h1><div class="skill-run-layout"><aside class="run-documents"><input id="runDocFilter" placeholder="Filtrera dokument…"><button id="toggleAllDocs">Välj alla</button><div id="runDocList" class="document-picker-list">';foreach($d['docs']as$x)echo'<label data-search="'.h(mb_strtolower($x['title'].' '.$x['rel_path'])).'"><input type="checkbox" value="'.h($x['rel_path']).'" '.(in_array($x['rel_path'],$s['document_paths'],true)?'checked':'').'><span><strong>'.h($x['title']).'</strong><small>'.h($x['rel_path']).'</small></span></label>';echo'</div><p id="selectionCount"></p></aside><div class="run-workspace"><textarea id="runTask" placeholder="Kompletterande uppdrag"></textarea><button id="runSkillBtn" class="btn-primary">Kör '.h($s['name']).'</button><section id="runResultPanel" class="run-result" hidden><span id="runStatus"></span><pre id="runResult"></pre><div id="resultActions" hidden><input id="resultTitle" value="Resultat – '.h($s['name']).'"><button id="saveResultBtn">Spara</button><button id="copyResultBtn">Kopiera</button></div></section></div></div></section>';$sc='<script>(()=>{const RUN_AI='.j($d['ai']).',cs=[...document.querySelectorAll("#runDocList input")],b=document.getElementById("runSkillBtn"),r=document.getElementById("runResult"),p=document.getElementById("runResultPanel"),a=document.getElementById("resultActions"),c=document.getElementById("selectionCount");const u=()=>c.textContent=cs.filter(x=>x.checked).length+" dokument valda";cs.forEach(x=>x.onchange=u);u();b.onclick=async()=>{p.hidden=false;r.textContent="";const payload={skill:'.j($s['slug']).',document_paths:cs.filter(x=>x.checked).map(x=>x.value),task:document.getElementById("runTask").value};if(RUN_AI.provider==="ollama"){const prepared=await postJSON("/api/skills/prepare",payload);let answer="";await window.localOllama.stream(RUN_AI,prepared.messages,token=>{answer+=token;r.textContent=answer});}else{const x=await fetch("/api/skills/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!x.ok){r.textContent=(await x.json()).error;return}r.textContent=await x.text()}a.hidden=false};document.getElementById("copyResultBtn").onclick=()=>navigator.clipboard.writeText(r.textContent);document.getElementById("saveResultBtn").onclick=async()=>{const x=await postJSON("/api/skills/save-result",{skill:'.j($s['slug']).',title:document.getElementById("resultTitle").value,body:r.textContent});location.href=x.url}})()</script>';page('Kör '.$s['name'],ob_get_clean(),$sc,$endpoint);}
